return items.map(item => {
  const raw = item.json.body?.candidate ?? item.json.candidate ?? item.json;

  if (raw.pageContent && raw.metadata) {
    return {
      json: {
        id: raw.id,
        profile_id: raw.profile_id || raw.metadata.profile_id,
        user_id: raw.user_id || raw.metadata.user_id,
        pageContent: raw.pageContent,
        metadata: raw.metadata
      }
    };
  }

  const c = raw;

  const safeArray = value => {
    if (!value) return [];
    if (Array.isArray(value)) return value;

    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  };

  const safeObject = value => {
    if (!value) return {};
    if (typeof value === 'object' && !Array.isArray(value)) return value;

    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed)
        ? parsed
        : {};
    } catch {
      return {};
    }
  };

  const skills = safeArray(c.skills_json);
  const education = safeArray(c.education_json);
  const strengths = safeArray(c.strengths_json);
  const weaknesses = safeArray(c.weaknesses_json);
  const experience = safeObject(c.experience_json);

  const stableId = c.pinecone_doc_id || `candidate_user_${c.user_id || c.id}`;

  const pageContent = `
Candidate Name: ${c.candidate_name || 'Not specified'}
Candidate Profile ID: ${c.id || 'Not specified'}
User ID: ${c.user_id || 'Not specified'}
Candidate Email: ${c.candidate_email || 'Not specified'}
Phone: ${c.phone || 'Not specified'}
Location: ${c.location || 'Not specified'}
Job Title: ${c.job_title || 'Not specified'}
Experience Level: ${c.experience_level || 'Not specified'}
Years Experience: ${c.years_experience ?? 'Not specified'}
ATS Score: ${c.ats_score ?? 'Not specified'}
Analysis Status: ${c.analysis_status || 'Not specified'}

Professional Summary:
${c.summary_text || 'Not specified'}

Technical Skills:
${skills.length ? skills.join(', ') : 'Not specified'}

Education:
${education.length ? JSON.stringify(education, null, 2) : 'Not specified'}

Projects And Experience:
${Object.keys(experience).length ? JSON.stringify(experience, null, 2) : 'Not specified'}

Strengths:
${strengths.length ? strengths.join(', ') : 'Not specified'}

Weaknesses:
${weaknesses.length ? weaknesses.join(', ') : 'Not specified'}

Recruitment Keywords:
${[
  c.candidate_name,
  c.job_title,
  c.location,
  c.experience_level,
  c.years_experience != null ? `${c.years_experience} years experience` : null,
  ...skills,
  ...strengths
].filter(Boolean).join(', ')}
`.trim();

  return {
    json: {
      id: stableId,
      profile_id: c.id,
      user_id: c.user_id,
      pageContent,
      metadata: {
        pinecone_id: stableId,
        profile_id: c.id,
        user_id: c.user_id,
        cv_id: c.cv_id,
        analysis_id: c.analysis_id,
        candidate_name: c.candidate_name || '',
        candidate_email: c.candidate_email || '',
        phone: c.phone || '',
        location: c.location || '',
        job_title: c.job_title || '',
        experience_level: c.experience_level || '',
        years_experience:
          c.years_experience != null
            ? Number(c.years_experience)
            : null,
        ats_score:
          c.ats_score != null
            ? Number(c.ats_score)
            : null,
        analysis_status: c.analysis_status || '',
        skills,
        education,
        experience,
        strengths,
        weaknesses,
        summary_text: c.summary_text || ''
      }
    }
  };
});

return items.filter(item => {
  const c = item.json.body?.candidate;

  return (
    c &&
    c.ats_score !== null &&
    c.ats_score > 0 &&
    Array.isArray(c.skills_json) &&
    c.skills_json.length > 0 &&
    c.summary_text &&
    c.summary_text.trim().length > 0
  );
});

